const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma/client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ============================================\n// ENUMS\n// ============================================\n\nenum RoleCode {\n  ADMINISTRATEUR\n  GESTIONNAIRE\n  RESPONSABLE_DEPARTEMENT\n  ENSEIGNANT\n  DIRECTION\n  ETUDIANT\n}\n\n// Fournisseur d'authentification — L0-14 Interface AuthProvider\n// Permet d'authentifier via le fournisseur LOCAL (mot de passe hashé) ou un\n// fournisseur externe futur (OIDC, LDAP/AD) sans impacter le RBAC.\nenum AuthProvider {\n  LOCAL\n  OIDC\n  LDAP\n}\n\nenum UserRole {\n  ADMIN\n  MANAGER\n  OPERATOR\n  VIEWER\n}\n\nenum TaskStatus {\n  TODO\n  IN_PROGRESS\n  IN_REVIEW\n  DONE\n  BLOCKED\n}\n\nenum TaskPriority {\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\nenum ProjectStatus {\n  PLANNING\n  ACTIVE\n  ON_HOLD\n  COMPLETED\n  ARCHIVED\n}\n\nenum SprintStatus {\n  PLANNING\n  ACTIVE\n  COMPLETED\n  CANCELLED\n}\n\nenum ActivityType {\n  CREATED\n  UPDATED\n  DELETED\n  STATUS_CHANGED\n  ASSIGNED\n  COMMENTED\n  MOVED\n}\n\n// Statut d'une année universitaire — L1-02\nenum AnneeStatut {\n  PREPARATION\n  ACTIVE\n  CLOTUREE\n}\n\n// Statut d'une répartition — L2-06\nenum RepartitionStatut {\n  BROUILLON\n  VALIDEE\n  ROUVERTE\n}\n\n// Type de demande de modification — L2-15\nenum DemandeType {\n  ANOMALIE\n  MODIFICATION\n}\n\n// Statut de demande de modification — L2-15\nenum DemandeStatut {\n  OUVERTE\n  TRAITEE\n  REFUSEE\n}\n\n// Type de groupe hiérarchique — L1-04\nenum GroupeType {\n  SECTION\n  GROUPE\n  SOUS_GROUPE\n}\n\n// Niveau d'exigence d'équipement — L1-11\nenum ExigenceNiveau {\n  OBLIGATOIRE\n  SOUHAITE\n}\n\n// Jour de la semaine pour la grille horaire — L1-17\nenum JourSemaine {\n  LUNDI\n  MARDI\n  MERCREDI\n  JEUDI\n  VENDREDI\n  SAMEDI\n}\n\n// Grille d'affichage (normale ou Ramadan) — L1-22\nenum GrilleAffichage {\n  NORMALE\n  RAMADAN\n}\n\nenum ContrainteCategorie {\n  DURE\n  SOUPLE\n}\n\nenum ContraintePortee {\n  GLOBALE\n  ENSEIGNANT\n  GROUPE\n  SALLE\n  MODULE\n}\n\nenum ContrainteNature {\n  REGLE\n  VOEU\n}\n\nenum FetSupport {\n  NATIF\n  PARTIEL\n  AUCUN\n}\n\n// Classe d'une règle du catalogue — L3-02\nenum ClasseRegle {\n  HARD_CONSTRAINT\n  SOFT_CONSTRAINT\n  BUSINESS_VALIDATION\n  INFORMATIONAL\n}\n\n// Traduction technique d'une règle vers FET — L3-02\nenum TraductionFET {\n  FET_SUPPORTED\n  FET_TRANSFORMED\n  APPLICATION_ONLY\n}\n\n// ============================================\n// MODELS\n// ============================================\n\nmodel User {\n  id                 String       @id @default(uuid()) @db.Uuid\n  email              String       @unique\n  // Optionnel : un compte authentifié via un fournisseur externe (OIDC/LDAP)\n  // n'a pas de mot de passe local.\n  passwordHash       String?\n  firstName          String       @map(\"nom\")\n  lastName           String       @map(\"prenom\")\n  isActive           Boolean      @default(true) @map(\"actif\")\n  desactiveLe        DateTime?\n  failedAttempts     Int          @default(0)\n  lockedUntil        DateTime?\n  mfaSecret          String?\n  mfaActive          Boolean      @default(false)\n  mustChangePassword Boolean      @default(false)\n  passwordChangedAt  DateTime     @default(now())\n  lastLoginAt        DateTime?\n  // Fournisseur d'authentification (LOCAL par défaut, OIDC/LDAP pour le SSO futur) — L0-14\n  provider           AuthProvider @default(LOCAL)\n  // Identifiant sujet du fournisseur externe (ex. sub OIDC), unique par fournisseur — L0-14\n  providerSubject    String?      @unique\n  createdAt          DateTime     @default(now())\n  updatedAt          DateTime     @updatedAt\n\n  // Relations\n  roles                UserSystemRole[]\n  assignedTasks        Task[]                @relation(\"AssignedTasks\")\n  createdTasks         Task[]                @relation(\"CreatedTasks\")\n  comments             Comment[]\n  activities           Activity[]\n  projectMembers       ProjectMember[]\n  sprintMembers        SprintMember[]\n  refreshTokens        RefreshToken[]\n  passwordHistory      PasswordHistory[]\n  resetTokens          PasswordResetToken[]\n  demandesModification DemandeModification[]\n\n  @@index([email])\n  @@index([isActive])\n  @@map(\"users\")\n}\n\nmodel UserSystemRole {\n  id              String   @id @default(uuid()) @db.Uuid\n  userId          String   @db.Uuid\n  role            RoleCode\n  departementCode String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, role, departementCode])\n  @@map(\"user_roles\")\n}\n\nmodel RefreshToken {\n  id             String    @id @default(uuid()) @db.Uuid\n  userId         String    @db.Uuid\n  familyId       String    @db.Uuid\n  tokenHash      String    @unique\n  expiresAt      DateTime\n  revokedAt      DateTime?\n  lastActivityAt DateTime  @default(now())\n  userAgent      String?\n  ip             String?\n  createdAt      DateTime  @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, familyId])\n  @@map(\"refresh_tokens\")\n}\n\nmodel PasswordHistory {\n  id           String   @id @default(uuid()) @db.Uuid\n  userId       String   @db.Uuid\n  passwordHash String\n  createdAt    DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, createdAt])\n  @@map(\"password_history\")\n}\n\nmodel PasswordResetToken {\n  id         String    @id @default(uuid()) @db.Uuid\n  userId     String    @db.Uuid\n  tokenHash  String    @unique\n  expiresAt  DateTime\n  usedAt     DateTime?\n  demandePar String    @db.Uuid\n  createdAt  DateTime  @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"password_reset_tokens\")\n}\n\nmodel Project {\n  id          String        @id @default(uuid()) @db.Uuid\n  name        String\n  description String?\n  key         String        @unique\n  status      ProjectStatus @default(PLANNING)\n  startDate   DateTime?\n  endDate     DateTime?\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  members ProjectMember[]\n  tasks   Task[]\n  sprints Sprint[]\n  columns BoardColumn[]\n\n  @@index([key])\n  @@index([status])\n  @@map(\"projects\")\n}\n\nmodel ProjectMember {\n  id        String   @id @default(uuid()) @db.Uuid\n  projectId String   @db.Uuid\n  userId    String   @db.Uuid\n  role      UserRole @default(VIEWER)\n  joinedAt  DateTime @default(now())\n\n  project Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, userId])\n  @@index([projectId])\n  @@index([userId])\n  @@map(\"project_members\")\n}\n\nmodel BoardColumn {\n  id        String   @id @default(uuid()) @db.Uuid\n  projectId String   @db.Uuid\n  name      String\n  position  Int\n  color     String   @default(\"#6366f1\")\n  isDone    Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  project Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  tasks   Task[]\n\n  @@index([projectId])\n  @@index([position])\n  @@map(\"board_columns\")\n}\n\nmodel Task {\n  id          String       @id @default(uuid()) @db.Uuid\n  projectId   String       @db.Uuid\n  columnId    String?      @db.Uuid\n  title       String\n  description String?\n  status      TaskStatus   @default(TODO)\n  priority    TaskPriority @default(MEDIUM)\n  storyPoints Int?\n  position    Int          @default(0)\n  dueDate     DateTime?\n  startedAt   DateTime?\n  completedAt DateTime?\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  project      Project      @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  column       BoardColumn? @relation(fields: [columnId], references: [id], onDelete: SetNull)\n  assignee     User?        @relation(\"AssignedTasks\", fields: [assigneeId], references: [id], onDelete: SetNull)\n  assigneeId   String?      @db.Uuid\n  creator      User         @relation(\"CreatedTasks\", fields: [creatorId], references: [id], onDelete: Restrict)\n  creatorId    String       @db.Uuid\n  sprint       Sprint?      @relation(fields: [sprintId], references: [id], onDelete: SetNull)\n  sprintId     String?      @db.Uuid\n  parentTask   Task?        @relation(\"Subtasks\", fields: [parentTaskId], references: [id], onDelete: SetNull)\n  parentTaskId String?      @db.Uuid\n  subtasks     Task[]       @relation(\"Subtasks\")\n  comments     Comment[]\n  activities   Activity[]\n  tags         TaskTag[]\n\n  @@index([projectId])\n  @@index([columnId])\n  @@index([assigneeId])\n  @@index([sprintId])\n  @@index([status])\n  @@index([parentTaskId])\n  @@map(\"tasks\")\n}\n\nmodel Sprint {\n  id        String       @id @default(uuid()) @db.Uuid\n  projectId String       @db.Uuid\n  name      String\n  goal      String?\n  status    SprintStatus @default(PLANNING)\n  startDate DateTime\n  endDate   DateTime\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n\n  project Project        @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  tasks   Task[]\n  members SprintMember[]\n\n  @@index([projectId])\n  @@index([status])\n  @@map(\"sprints\")\n}\n\nmodel SprintMember {\n  id       String @id @default(uuid()) @db.Uuid\n  sprintId String @db.Uuid\n  userId   String @db.Uuid\n\n  sprint Sprint @relation(fields: [sprintId], references: [id], onDelete: Cascade)\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([sprintId, userId])\n  @@index([sprintId])\n  @@index([userId])\n  @@map(\"sprint_members\")\n}\n\nmodel Comment {\n  id        String   @id @default(uuid()) @db.Uuid\n  taskId    String   @db.Uuid\n  userId    String   @db.Uuid\n  content   String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  task Task @relation(fields: [taskId], references: [id], onDelete: Cascade)\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([taskId])\n  @@index([userId])\n  @@map(\"comments\")\n}\n\nmodel Tag {\n  id        String   @id @default(uuid()) @db.Uuid\n  name      String   @unique\n  color     String   @default(\"#6366f1\")\n  createdAt DateTime @default(now())\n\n  tasks TaskTag[]\n\n  @@map(\"tags\")\n}\n\nmodel TaskTag {\n  taskId String @db.Uuid\n  tagId  String @db.Uuid\n\n  task Task @relation(fields: [taskId], references: [id], onDelete: Cascade)\n  tag  Tag  @relation(fields: [tagId], references: [id], onDelete: Cascade)\n\n  @@id([taskId, tagId])\n  @@map(\"task_tags\")\n}\n\nmodel Activity {\n  id        String       @id @default(uuid()) @db.Uuid\n  taskId    String?      @db.Uuid\n  userId    String       @db.Uuid\n  type      ActivityType\n  field     String?\n  oldValue  String?\n  newValue  String?\n  metadata  Json?\n  createdAt DateTime     @default(now())\n\n  task Task? @relation(fields: [taskId], references: [id], onDelete: Cascade)\n  user User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([taskId])\n  @@index([userId])\n  @@index([type])\n  @@index([createdAt])\n  @@map(\"activities\")\n}\n\n// Paramètres de sécurité (ligne unique, CHECK id = 1) — EX-SEC-04\nmodel ParametreSecurite {\n  id                        Int        @id @default(1)\n  longueurMin               Int        @default(12)\n  regles                    Json       @default(\"{}\")\n  expirationJours           Int        @default(0)\n  historique                Int        @default(5)\n  maxEchecs                 Int        @default(5)\n  verrouillageMinutes       Int        @default(15)\n  inactiviteMinutes         Int        @default(30)\n  mfaRoles                  RoleCode[] @default([ADMINISTRATEUR])\n  conservationAuditJours    Int?\n  conservationSecuriteJours Int        @default(365)\n  updatedAt                 DateTime   @updatedAt\n  updatedBy                 String?    @db.Uuid\n\n  @@map(\"parametres_securite\")\n}\n\n// Circuit de validation et de publication (ligne unique, CHECK id = 1) — EX-WFL-02\nmodel ParametreWorkflow {\n  id                        Int      @id @default(1)\n  validationPlanningRequise Boolean  @default(true)\n  publicationRequise        Boolean  @default(true)\n  updatedAt                 DateTime @updatedAt\n  updatedBy                 String?  @db.Uuid\n\n  @@map(\"parametres_workflow\")\n}\n\n// Journal de sécurité, séparé de l'audit métier — EX-SEC-09\nmodel SecurityEvent {\n  id        BigInt   @id @default(autoincrement())\n  at        DateTime @default(now())\n  type      String\n  userId    String?  @db.Uuid\n  email     String?\n  ip        String?\n  userAgent String?\n  requestId String?\n  details   Json?\n\n  @@index([type, at])\n  @@index([userId, at])\n  @@map(\"security_events\")\n}\n\n// Audit append-only — EX-AUD-01\nmodel AuditLog {\n  id             BigInt   @id @default(autoincrement())\n  at             DateTime @default(now())\n  userId         String?  @db.Uuid\n  action         String\n  objetType      String\n  objetId        String\n  ancienneValeur Json?\n  nouvelleValeur Json?\n  versionId      String?  @db.Uuid\n  motif          String?\n  requestId      String?\n  ip             String?\n\n  @@index([objetType, objetId])\n  @@index([versionId, at])\n  @@index([userId, at])\n  @@map(\"audit_logs\")\n}\n\n// ============================================\n// Calendrier scolaire (L1-01 : années & semestres)\n// ============================================\n\nmodel Annee {\n  id         String      @id @default(uuid()) @db.Uuid\n  numero     Int // ex: 2026\n  code       String // ex: \"2026-2027\"\n  nbSemaines Int         @default(14)\n  statut     AnneeStatut @default(PREPARATION)\n  createdAt  DateTime    @default(now())\n  updatedAt  DateTime    @updatedAt\n\n  semestres      Semestre[]\n  departements   Departement[]\n  enseignants    Enseignant[]\n  chargeRuleSets ChargeRuleSet[]\n\n  @@unique([code])\n  @@unique([numero])\n  @@map(\"annees\")\n}\n\nmodel Semestre {\n  id           String   @id @default(uuid()) @db.Uuid\n  numero       Int // 1 ou 2\n  anneeId      String   @db.Uuid\n  annee        Annee    @relation(fields: [anneeId], references: [id], onDelete: Cascade)\n  nbSemaines   Int      @default(14)\n  grilleParams Json? // {jours:[{jour, debut, fin, pauses:[{debut, fin}]}]} pour regenerer la grille\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  groupes              Groupe[]\n  decharges            Decharge[]\n  creneaux             Creneau[]\n  indisponibilites     Indisponibilite[]\n  contrainteInstances  ContrainteInstance[]\n  repartitions         Repartition[]\n  demandesModification DemandeModification[]\n\n  @@unique([anneeId, numero])\n  @@map(\"semestres\")\n}\n\n// ============================================\n// Grille horaire (L1-17 : créneaux et pauses)\n// ============================================\n\nmodel Creneau {\n  id         String      @id @default(uuid()) @db.Uuid\n  semestreId String      @db.Uuid\n  semestre   Semestre    @relation(fields: [semestreId], references: [id], onDelete: Cascade)\n  jour       JourSemaine\n  ordre      Int // position dans la journée (1..n)\n  heureDebut DateTime    @db.Time\n  heureFin   DateTime    @db.Time\n  estPause   Boolean     @default(false)\n  estActive  Boolean     @default(true)\n  createdAt  DateTime    @default(now())\n  updatedAt  DateTime    @updatedAt\n\n  affichages CreneauAffichage[]\n\n  @@unique([semestreId, jour, ordre])\n  @@index([semestreId, jour])\n  @@map(\"creneaux\")\n}\n\n// ============================================\n// Correspondance d'affichage Ramadan (L1-22 : EX-CAL-04)\n// La grille NORMALE est dérivée de Creneau ; RAMADAN associe un horaire d'affichage libre par créneau.\n// ============================================\n\nmodel CreneauAffichage {\n  id         String          @id @default(uuid()) @db.Uuid\n  creneauId  String          @db.Uuid\n  grille     GrilleAffichage @default(RAMADAN)\n  heureDebut DateTime        @db.Time(0)\n  heureFin   DateTime        @db.Time(0) // durée libre, pas de contrainte de 30 minutes\n\n  creneau Creneau @relation(fields: [creneauId], references: [id], onDelete: Cascade)\n\n  @@unique([creneauId, grille])\n  @@index([creneauId])\n  @@map(\"creneau_affichage\")\n}\n\n// ============================================\n// Structure académique (L1-03 : départements, formations, niveaux)\n// ============================================\n\nmodel Departement {\n  id        String   @id @default(uuid()) @db.Uuid\n  anneeId   String   @db.Uuid\n  annee     Annee    @relation(fields: [anneeId], references: [id], onDelete: Cascade)\n  code      String // ex: \"INFO\", \"MATH\"\n  libelle   String // ex: \"Informatique\", \"Mathématiques\"\n  ordre     Int      @default(0)\n  originId  String? // ID d'origine externe (synchronisation)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  formations   Formation[]\n  enseignants  Enseignant[]\n  salles       Salle[]\n  repartitions Repartition[]\n\n  @@unique([anneeId, code])\n  @@index([anneeId, ordre])\n  @@map(\"departements\")\n}\n\nmodel Formation {\n  id            String      @id @default(uuid()) @db.Uuid\n  departementId String      @db.Uuid\n  departement   Departement @relation(fields: [departementId], references: [id], onDelete: Cascade)\n  code          String // ex: \"L3-INFO\"\n  libelle       String // ex: \"Licence 3 Informatique\"\n  ordre         Int         @default(0)\n  originId      String? // ID d'origine externe (synchronisation)\n  createdAt     DateTime    @default(now())\n  updatedAt     DateTime    @updatedAt\n\n  niveaux Niveau[]\n\n  @@unique([departementId, code])\n  @@index([departementId, ordre])\n  @@map(\"formations\")\n}\n\nmodel Niveau {\n  id          String    @id @default(uuid()) @db.Uuid\n  formationId String    @db.Uuid\n  formation   Formation @relation(fields: [formationId], references: [id], onDelete: Cascade)\n  code        String // ex: \"L3\"\n  libelle     String // ex: \"Licence 3\"\n  ordre       Int       @default(0)\n  originId    String? // ID d'origine externe (synchronisation)\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  groupes Groupe[]\n  modules Module[]\n\n  @@unique([formationId, code])\n  @@index([formationId, ordre])\n  @@map(\"niveaux\")\n}\n\n// ============================================\n// Groupes hiérarchiques (L1-04)\n// ============================================\n\nmodel Groupe {\n  id           String        @id @default(uuid()) @db.Uuid\n  niveauId     String        @db.Uuid\n  niveau       Niveau        @relation(fields: [niveauId], references: [id], onDelete: Cascade)\n  semestreId   String        @db.Uuid\n  semestre     Semestre      @relation(fields: [semestreId], references: [id], onDelete: Cascade)\n  parentId     String?       @db.Uuid\n  parent       Groupe?       @relation(\"GroupesHierarchie\", fields: [parentId], references: [id])\n  enfants      Groupe[]      @relation(\"GroupesHierarchie\")\n  type         GroupeType\n  code         String // ex: \"INFO-L3-S1\"\n  libelle      String // ex: \"L3 Informatique Semestre 1\"\n  ordre        Int           @default(0)\n  effectif     Int           @default(0)\n  originId     String? // ID d'origine externe (synchronisation)\n  affectations Affectation[]\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n\n  @@unique([niveauId, semestreId, code])\n  @@index([niveauId, semestreId, ordre])\n  @@index([semestreId])\n  @@index([parentId])\n  @@map(\"groupes\")\n}\n\n// ============================================\n// Modules, types d'enseignement et grades (L1-05)\n// ============================================\n\nenum TypeEnseignementCode {\n  CM\n  TD\n  TP\n  CI\n  AUTRE\n}\n\nmodel TypeEnseignement {\n  id            String               @id @default(uuid()) @db.Uuid\n  code          TypeEnseignementCode\n  libelle       String\n  activityTagId String?              @db.Uuid\n  activityTag   ActivityTag?         @relation(fields: [activityTagId], references: [id], onDelete: SetNull)\n  createdAt     DateTime             @default(now())\n  updatedAt     DateTime             @updatedAt\n\n  modules             Module[]\n  exigencesEquipement ExigenceEquipement[] @relation(\"TypeExigenceEquipement\")\n  chargeCoefficients  ChargeCoefficient[]\n  affectations        Affectation[]\n\n  @@unique([code])\n  @@map(\"types_enseignement\")\n}\n\nenum GradeCode {\n  MC\n  MCF\n  PR\n  ATER\n  AUTRE\n}\n\nmodel Grade {\n  id        String    @id @default(uuid()) @db.Uuid\n  code      GradeCode\n  libelle   String\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  modules               Module[]\n  enseignants           Enseignant[]\n  chargeReferenceGrades ChargeReferenceGrade[]\n\n  @@unique([code])\n  @@map(\"grades\")\n}\n\nmodel Module {\n  id                  String               @id @default(uuid()) @db.Uuid\n  niveauId            String               @db.Uuid\n  niveau              Niveau               @relation(fields: [niveauId], references: [id], onDelete: Cascade)\n  typeId              String               @db.Uuid\n  type                TypeEnseignement     @relation(fields: [typeId], references: [id], onDelete: Cascade)\n  gradeId             String?              @db.Uuid\n  grade               Grade?               @relation(fields: [gradeId], references: [id], onDelete: SetNull)\n  code                String // ex: \"INFO301\"\n  libelle             String // ex: \"Algorithmique avancée\"\n  semestreNumero      Int // 1 ou 2\n  credits             Int?                 @default(6)\n  effectifMax         Int? // capacité max du module\n  originId            String? // ID d'origine externe (synchronisation)\n  createdAt           DateTime             @default(now())\n  updatedAt           DateTime             @updatedAt\n  enseignantModules   EnseignantModule[]\n  exigencesEquipement ExigenceEquipement[] @relation(\"ModuleExigenceEquipement\")\n  moduleVolumes       ModuleVolume[]\n  affectations        Affectation[]\n\n  @@unique([niveauId, code, semestreNumero])\n  @@index([niveauId])\n  @@index([typeId])\n  @@index([gradeId])\n  @@map(\"modules\")\n}\n\n// ============================================\n// Module Volumes (L2-01)\n// ============================================\n\nmodel ModuleVolume {\n  id        String   @id @default(uuid()) @db.Uuid\n  moduleId  String   @db.Uuid\n  module    Module   @relation(fields: [moduleId], references: [id], onDelete: Cascade)\n  type      String // CM, TD, TP, CI, AUTRE\n  volume    Int // en minutes, multiple de 30\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([moduleId, type])\n  @@index([moduleId])\n  @@map(\"module_volumes\")\n}\n\n// ============================================\n// Jeux de règles de charge (L2-03)\n// ============================================\n\nenum PeriodeRegle {\n  HEBDOMADAIRE\n  SEMESTRIELLE\n  ANNUELLE\n}\n\nmodel ChargeRuleSet {\n  id        String       @id @default(uuid()) @db.Uuid\n  numero    Int\n  periode   PeriodeRegle\n  seuil     Int?\n  plafond   Int?\n  arrondi   Int?\n  publieLe  DateTime?\n  anneeId   String?      @db.Uuid\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n\n  annee           Annee?                 @relation(fields: [anneeId], references: [id], onDelete: SetNull)\n  referenceGrades ChargeReferenceGrade[]\n  coefficients    ChargeCoefficient[]\n\n  @@unique([numero])\n  @@index([periode])\n  @@index([anneeId])\n  @@map(\"charge_rule_sets\")\n}\n\nmodel ChargeReferenceGrade {\n  id          String   @id @default(uuid()) @db.Uuid\n  rulesetId   String   @map(\"ruleSetId\") @db.Uuid\n  gradeId     String?  @db.Uuid\n  coefficient Decimal  @db.Decimal\n  createdAt   DateTime @default(now())\n\n  ruleset ChargeRuleSet @relation(fields: [rulesetId], references: [id], onDelete: Cascade)\n  grade   Grade?        @relation(fields: [gradeId], references: [id], onDelete: SetNull)\n\n  @@unique([rulesetId, gradeId])\n  @@index([rulesetId])\n  @@index([gradeId])\n  @@map(\"charge_reference_grades\")\n}\n\nmodel ChargeCoefficient {\n  id          String   @id @default(uuid()) @db.Uuid\n  rulesetId   String   @map(\"ruleSetId\") @db.Uuid\n  typeId      String   @db.Uuid\n  coefficient Decimal  @db.Decimal\n  createdAt   DateTime @default(now())\n\n  ruleset ChargeRuleSet    @relation(fields: [rulesetId], references: [id], onDelete: Cascade)\n  type    TypeEnseignement @relation(fields: [typeId], references: [id], onDelete: Cascade)\n\n  @@unique([rulesetId, typeId])\n  @@index([rulesetId])\n  @@index([typeId])\n  @@map(\"charge_coefficients\")\n}\n\n// ============================================\n// Activity Tags (L1-06)\n// ============================================\n\nmodel ActivityTag {\n  id        String   @id @default(uuid()) @db.Uuid\n  code      String   @unique\n  libelle   String\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  typesEnseignement TypeEnseignement[]\n  salleActivityTags SalleActivityTag[] @relation(\"ActivityTagSalleActivityTag\")\n  affectations      Affectation[]\n\n  @@index([code])\n  @@index([isActive])\n  @@map(\"activity_tags\")\n}\n\nmodel Enseignant {\n  id                String             @id @default(uuid()) @db.Uuid\n  matricule         String\n  nom               String\n  prenom            String\n  email             String             @unique\n  telephone         String?\n  isActive          Boolean            @default(true)\n  anneeId           String             @db.Uuid\n  annee             Annee              @relation(fields: [anneeId], references: [id], onDelete: Cascade)\n  departementId     String             @db.Uuid\n  departement       Departement        @relation(fields: [departementId], references: [id], onDelete: Cascade)\n  gradeId           String?            @db.Uuid\n  grade             Grade?             @relation(fields: [gradeId], references: [id], onDelete: SetNull)\n  originId          String? // ID d'origine externe (synchronisation)\n  enseignantModules EnseignantModule[]\n  decharges         Decharge[]\n  indisponibilites  Indisponibilite[]\n  affectations      Affectation[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([anneeId, matricule])\n  @@index([departementId])\n  @@index([gradeId])\n  @@index([email])\n  @@map(\"enseignants\")\n}\n\nmodel EnseignantModule {\n  enseignantId String     @db.Uuid\n  moduleId     String     @db.Uuid\n  enseignant   Enseignant @relation(fields: [enseignantId], references: [id], onDelete: Cascade)\n  module       Module     @relation(fields: [moduleId], references: [id], onDelete: Cascade)\n\n  @@id([enseignantId, moduleId])\n  @@map(\"enseignant_modules\")\n}\n\n// ============================================\n// Décharges enseignant (L1-08)\n// ============================================\n\nmodel Decharge {\n  id           String     @id @default(uuid()) @db.Uuid\n  heures       Float // heures équivalentes de décharge\n  enseignantId String     @db.Uuid\n  enseignant   Enseignant @relation(fields: [enseignantId], references: [id], onDelete: Cascade)\n  semestreId   String     @db.Uuid\n  semestre     Semestre   @relation(fields: [semestreId], references: [id], onDelete: Cascade)\n  createdAt    DateTime   @default(now())\n  updatedAt    DateTime   @updatedAt\n\n  @@unique([enseignantId, semestreId])\n  @@index([enseignantId])\n  @@index([semestreId])\n  @@map(\"decharges\")\n}\n\n// ============================================\n// Salles (L1-10 : types de salle, salles, équipements)\n// ============================================\n\nmodel TypeSalle {\n  id        String   @id @default(uuid()) @db.Uuid\n  code      String // ex: \"AMPHI\", \"TD\", \"TP\", \"BUREAU\"\n  libelle   String // ex: \"Amphithéâtre\", \"Salle de TD\", \"Bureau\"\n  estActive Boolean  @default(true)\n  originId  String? // ID d'origine externe (synchronisation)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  salles Salle[]\n\n  @@unique([code])\n  @@map(\"types_salle\")\n}\n\n// ============================================\n// Référentiel des sites (L1-14)\n// ============================================\n\nmodel Site {\n  id           String   @id @default(uuid()) @db.Uuid\n  code         String   @unique // ex: \"SITE-PRINCIPAL\"\n  libelle      String // ex: \"Campus Principal\"\n  estPrincipal Boolean  @default(false) // un seul site principal par défaut\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  salles Salle[]\n\n  @@index([estPrincipal])\n  @@map(\"sites\")\n}\n\nmodel Salle {\n  id                  String   @id @default(uuid()) @db.Uuid\n  code                String // ex: \"AMPHI-A\"\n  libelle             String // ex: \"Amphithéâtre A\"\n  siteId              String?  @db.Uuid // rattachement à un site (null = non affecté)\n  capaciteMax         Int // capacité maximale (> 0)\n  capaciteRecommandee Int? // capacité recommandée (<= capaciteMax)\n  accesPMR            Boolean  @default(false)\n  commentaire         String?\n  estActive           Boolean  @default(true)\n  departementId       String?  @db.Uuid // null = salle partagée\n  typeSalleId         String?  @db.Uuid\n  originId            String? // ID d'origine externe (synchronisation)\n  createdAt           DateTime @default(now())\n  updatedAt           DateTime @updatedAt\n\n  departement       Departement?       @relation(fields: [departementId], references: [id], onDelete: SetNull)\n  typeSalle         TypeSalle?         @relation(fields: [typeSalleId], references: [id], onDelete: SetNull)\n  site              Site?              @relation(fields: [siteId], references: [id], onDelete: SetNull)\n  equipements       SalleEquipement[]\n  salleActivityTags SalleActivityTag[] @relation(\"SalleActivityTag\")\n  indisponibilites  Indisponibilite[]\n\n  @@index([departementId])\n  @@index([typeSalleId])\n  @@index([siteId])\n  @@map(\"salles\")\n}\n\n// ============================================\n// Indisponibilités (L1-20 : enseignants et salles)\n// ============================================\n\nmodel Indisponibilite {\n  id           String      @id @default(uuid()) @db.Uuid\n  semestreId   String      @db.Uuid\n  semestre     Semestre    @relation(fields: [semestreId], references: [id], onDelete: Cascade)\n  jour         JourSemaine\n  ordre        Int // position dans la journée (1..n)\n  enseignantId String?     @db.Uuid\n  enseignant   Enseignant? @relation(fields: [enseignantId], references: [id], onDelete: Cascade)\n  salleId      String?     @db.Uuid\n  salle        Salle?      @relation(fields: [salleId], references: [id], onDelete: Cascade)\n  estActive    Boolean     @default(true)\n  createdAt    DateTime    @default(now())\n  updatedAt    DateTime    @updatedAt\n\n  @@unique([semestreId, jour, ordre, enseignantId, salleId])\n  @@index([semestreId, jour, ordre])\n  @@index([enseignantId])\n  @@index([salleId])\n  @@map(\"indisponibilites\")\n}\n\nmodel Equipement {\n  id        String   @id @default(uuid()) @db.Uuid\n  code      String // ex: \"VIDEOPROJ\", \"TABLEAU\"\n  libelle   String // ex: \"Vidéo projecteur\", \"Tableau blanc\"\n  estActive Boolean  @default(true)\n  originId  String? // ID d'origine externe (synchronisation)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  salles              SalleEquipement[]\n  exigencesEquipement ExigenceEquipement[] @relation(\"EquipementExigenceEquipement\")\n\n  @@unique([code])\n  @@map(\"equipements\")\n}\n\nmodel SalleEquipement {\n  salleId      String     @db.Uuid\n  equipementId String     @db.Uuid\n  salle        Salle      @relation(fields: [salleId], references: [id], onDelete: Cascade)\n  equipement   Equipement @relation(fields: [equipementId], references: [id], onDelete: Cascade)\n\n  @@id([salleId, equipementId])\n  @@map(\"salles_equipements\")\n}\n\n// ============================================ \n// Compatibilités salles / Activity Tags (L1-11)\n// ============================================\n\nmodel SalleActivityTag {\n  salleId       String @db.Uuid\n  activityTagId String @db.Uuid\n\n  salle Salle       @relation(\"SalleActivityTag\", fields: [salleId], references: [id], onDelete: Cascade)\n  tag   ActivityTag @relation(\"ActivityTagSalleActivityTag\", fields: [activityTagId], references: [id], onDelete: Cascade)\n\n  @@id([salleId, activityTagId])\n  @@map(\"salle_activity_tags\")\n}\n\n// ============================================\n// Exigences d'équipement par (module, type d'enseignement) (L1-11)\n// ============================================\n\nmodel ExigenceEquipement {\n  moduleId           String         @db.Uuid\n  typeEnseignementId String         @db.Uuid\n  equipementId       String         @db.Uuid\n  niveau             ExigenceNiveau @default(OBLIGATOIRE)\n\n  module     Module           @relation(\"ModuleExigenceEquipement\", fields: [moduleId], references: [id], onDelete: Cascade)\n  type       TypeEnseignement @relation(\"TypeExigenceEquipement\", fields: [typeEnseignementId], references: [id])\n  equipement Equipement       @relation(\"EquipementExigenceEquipement\", fields: [equipementId], references: [id])\n\n  @@id([moduleId, typeEnseignementId, equipementId])\n  @@map(\"exigences_equipement\")\n}\n\n// ============================================\n// Contraintes - L3-01\n// ============================================\n\nmodel ContrainteDefinition {\n  id            String              @id @default(uuid()) @db.Uuid\n  code          String              @unique\n  libelle       String\n  categorie     ContrainteCategorie\n  portee        ContraintePortee\n  classe        ClasseRegle         @default(HARD_CONSTRAINT)\n  traductionFET TraductionFET       @default(FET_SUPPORTED)\n  paramsSchema  Json\n  fetSupport    FetSupport          @default(NATIF)\n  actif         Boolean             @default(true)\n\n  instances ContrainteInstance[]\n\n  @@map(\"contrainte_definitions\")\n}\n\nmodel ContrainteInstance {\n  id           String           @id @default(uuid()) @db.Uuid\n  semestreId   String           @db.Uuid\n  definitionId String           @db.Uuid\n  enseignantId String?          @db.Uuid\n  groupeId     String?          @db.Uuid\n  salleId      String?          @db.Uuid\n  moduleId     String?          @db.Uuid\n  originId     String? // ID de l'instance source en cas de duplication\n  params       Json\n  poids        Int?\n  nature       ContrainteNature @default(REGLE)\n  commentaire  String?\n  actif        Boolean          @default(true)\n  creePar      String           @db.Uuid\n  creeLe       DateTime         @default(now())\n\n  semestre   Semestre             @relation(fields: [semestreId], references: [id], onDelete: Cascade)\n  definition ContrainteDefinition @relation(fields: [definitionId], references: [id], onDelete: Cascade)\n\n  @@index([semestreId, actif])\n  @@map(\"contrainte_instances\")\n}\n\n// ============================================\n// Répartitions (L2-06 : répartitions par département et semestre)\n// Une répartition lie un (semestre, département) avec un statut BROUILLON / VALIDEE / ROUVERTE.\n// ============================================\n\nmodel Repartition {\n  id            String            @id @default(uuid()) @db.Uuid\n  semestreId    String            @db.Uuid\n  departementId String            @db.Uuid\n  statut        RepartitionStatut @default(BROUILLON)\n  libelle       String?\n  createdAt     DateTime          @default(now())\n  updatedAt     DateTime          @updatedAt\n\n  semestre     Semestre      @relation(fields: [semestreId], references: [id], onDelete: Cascade)\n  departement  Departement   @relation(fields: [departementId], references: [id], onDelete: Cascade)\n  affectations Affectation[]\n\n  @@unique([semestreId, departementId])\n  @@index([semestreId])\n  @@index([departementId])\n  @@map(\"repartitions\")\n}\n\n// ============================================\n// Affectations d'enseignants aux cours/groupes (L2-07)\n// Une affectation lie un enseignant, un module, un type d'enseignement,\n// un groupe optionnel et une activité tag optionnel à une répartition.\n// Le volumeHebdoMinutes est calculé par le serveur (seancesParSemaine * dureeMinutes).\n// ============================================\n\nmodel Affectation {\n  id                 String   @id @default(uuid()) @db.Uuid\n  repartitionId      String   @db.Uuid\n  enseignantId       String   @db.Uuid\n  groupeId           String?  @db.Uuid\n  moduleId           String   @db.Uuid\n  typeEnseignementId String   @db.Uuid\n  activityTagId      String?  @db.Uuid\n  volumeHebdoMinutes Int // calculé par le serveur : seancesParSemaine * dureeMinutes\n  seancesParSemaine  Int // >= 1\n  dureeMinutes       Int // multiple de 30\n  estCmCommun        Boolean  @default(false)\n  workingRevision    Int      @default(1)\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  repartition      Repartition      @relation(fields: [repartitionId], references: [id], onDelete: Cascade)\n  enseignant       Enseignant       @relation(fields: [enseignantId], references: [id], onDelete: Cascade)\n  groupe           Groupe?          @relation(fields: [groupeId], references: [id], onDelete: SetNull)\n  module           Module           @relation(fields: [moduleId], references: [id], onDelete: Cascade)\n  typeEnseignement TypeEnseignement @relation(fields: [typeEnseignementId], references: [id], onDelete: Cascade)\n  activityTag      ActivityTag?     @relation(fields: [activityTagId], references: [id], onDelete: SetNull)\n\n  @@unique([repartitionId, enseignantId, moduleId, typeEnseignementId, groupeId])\n  @@index([repartitionId])\n  @@index([enseignantId])\n  @@index([moduleId])\n  @@index([typeEnseignementId])\n  @@index([groupeId])\n  @@map(\"affectations\")\n}\n\n// ============================================\n// Snapshots de validation (L2-12)\n// Un snapshot fige l'état d'une répartition validée\n// pour garantir l'immuabilité (ST §4.1.2).\n// ============================================\n\nmodel Snapshot {\n  id                String            @id @default(uuid()) @db.Uuid\n  repartitionId     String            @db.Uuid\n  tag               String // tag résolu (ex. numéro de version)\n  hash              String // hash de l'état figé\n  valideParId       String            @db.Uuid // userId du validateur\n  valideLe          DateTime          @default(now())\n  parAdministrateur Boolean           @default(false) // true si validé par un Administrateur\n  repartitionStatut RepartitionStatut\n  createdAt         DateTime          @default(now())\n\n  @@index([repartitionId])\n  @@map(\"snapshots\")\n}\n\nmodel SnapshotAffectation {\n  id                 String  @id @default(uuid()) @db.Uuid\n  snapshotId         String  @db.Uuid\n  enseignantId       String  @db.Uuid\n  groupeId           String? @db.Uuid\n  moduleId           String  @db.Uuid\n  typeEnseignementId String  @db.Uuid\n  activityTagId      String? @db.Uuid\n  volumeHebdoMinutes Int\n  seancesParSemaine  Int\n  dureeMinutes       Int\n  estCmCommun        Boolean\n  workingRevision    Int\n\n  @@index([snapshotId])\n  @@map(\"snapshot_affectations\")\n}\n\nmodel SnapshotCharge {\n  id              String   @id @default(uuid()) @db.Uuid\n  snapshotId      String   @db.Uuid\n  enseignantId    String   @db.Uuid\n  volumeBrut      Int // volume brut en minutes\n  chargeCalculee  Int // charge calculée en minutes\n  chargeReference Int // charge de référence en minutes\n  decharges       Int // décharges en minutes\n  serviceDu       Int // service dû en minutes\n  ecart           Int // écart en minutes\n  heuresSup       Int // heures supplémentaires en minutes\n  createdAt       DateTime @default(now())\n\n  @@index([snapshotId])\n  @@map(\"snapshot_charges\")\n}\n\n// ============================================\n// Demandes de modification (L2-15)\n// Une demande signale une anomalie ou demande une modification\n// de répartition, liée à un semestre et à un département.\n// ============================================\n\nmodel DemandeModification {\n  id              String        @id @default(uuid()) @db.Uuid\n  semestreId      String        @db.Uuid\n  departementCode String\n  auteurId        String        @db.Uuid\n  versionId       String?       @db.Uuid\n  type            DemandeType\n  cible           Json\n  motif           String\n  statut          DemandeStatut @default(OUVERTE)\n  reponse         String?\n  traiteePar      String?       @db.Uuid\n  createdAt       DateTime      @default(now())\n  traiteeLe       DateTime?\n\n  semestre Semestre @relation(fields: [semestreId], references: [id])\n  auteur   User     @relation(fields: [auteurId], references: [id])\n\n  @@index([departementCode, statut])\n  @@map(\"demandes_modification\")\n}\n"
}

